// Strips text that harnesses inject into "user" messages, and redacts secrets
// before anything leaves the machine for an LLM call.

const INJECTED_PREFIXES = [
  "This block is",
  "Continue working toward the active thread goal",
  "# Files mentioned by the user",
  "# AGENTS.md instructions",
  "Caveat: The messages below were generated by the user while running local commands",
];

export function stripInjected(raw: string): string {
  let text = raw;
  // Remove paired XML-ish blocks such as <system_instruction>…</system_instruction>,
  // <system-reminder>…</system-reminder>, <environment_context>…</environment_context>.
  for (let i = 0; i < 5; i++) {
    const next = text.replace(/<([a-zA-Z][\w:-]*)(\s[^>]*)?>[\s\S]*?<\/\1>/g, "");
    if (next === text) break;
    text = next;
  }
  // Drop unpaired opening tags left behind.
  text = text.replace(/<\/?[a-zA-Z][\w:-]*(\s[^>]*)?\/?>/g, "");
  // Codex desktop wraps the typed message under a "## My request:" heading.
  text = text.replace(/^#{1,3} My request:\s*/m, "").trim();
  if (INJECTED_PREFIXES.some((p) => text.startsWith(p))) return "";
  if (/^\[Request interrupted by user/.test(text)) return "";
  return text;
}

const SECRET_PATTERNS: RegExp[] = [
  /sk-[A-Za-z0-9_-]{16,}/g,
  /sk-ant-[A-Za-z0-9_-]{16,}/g,
  /gh[pousr]_[A-Za-z0-9]{20,}/g,
  /github_pat_[A-Za-z0-9_]{20,}/g,
  /AKIA[0-9A-Z]{16}/g,
  /xox[baprs]-[A-Za-z0-9-]{10,}/g,
  /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g,
  /(?<=\b(?:password|passwd|pwd|secret|token|api[_-]?key|apikey)\s*[:=]\s*)\S+/gi,
  /(?<=Bearer\s+)[A-Za-z0-9._~+/-]{16,}=*/g,
  /(?<=:\/\/[^\s:/@]+:)[^\s@]+(?=@)/g,
];

/** Long opaque tokens: mixed case + digits, no word separators. */
const OPAQUE = /(?<![\w/.-])[A-Za-z0-9_]{20,}={0,2}(?![\w/.-])/g;

export function redact(text: string): string {
  let out = text;
  for (const p of SECRET_PATTERNS) out = out.replace(p, "[REDACTED]");
  return out.replace(OPAQUE, (m) => (/[a-z]/.test(m) && /[A-Z]/.test(m) && /\d/.test(m) ? "[REDACTED]" : m));
}

export function truncate(text: string, max: number): string {
  const t = text.replace(/\s+/g, " ").trim();
  return t.length <= max ? t : t.slice(0, max - 1) + "…";
}
